import{z as m,x as n,o,c as p,q as A,j as l,D as s,d as E,s as i,S as r,b as t}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"softmax 替代与 softpick","description":"","frontmatter":{"title":"softmax 替代与 softpick","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/softmax-alternatives.md","filePath":"llm/softmax-alternatives.md","lastUpdated":1791413859000}'),B={name:"llm/softmax-alternatives.md"};function f(d,a,x,h,u,S){const e=n("Mermaid");return o(),p("div",null,[a[2]||(a[2]=A('<h1 id="softmax-替代与-softpick" tabindex="-1">softmax 替代与 softpick <a class="header-anchor" href="#softmax-替代与-softpick" aria-label="Permalink to &quot;softmax 替代与 softpick&quot;">​</a></h1><div class="epigraph"><p>Softmax 把权重钉在单纯形上；若需要稀疏、需要可关断、或不需要概率解释，就该换投影，而不是再叠一个门。</p><footer>—— Martins &amp; Astudillo, From Softmax to Sparsemax, ICML 2016；离开单纯形的路线上还有 softpick 一类可关断算子</footer></div><p><a href="/llm/sigmoid-attention">上一课</a>用逐点 sigmoid 离开单纯形。<a href="/llm/gated-attention">门控注意力</a>则留在 softmax 里事后调幅。本课把中间地带收齐：仍想要<strong>行内竞争</strong>，但不想要 softmax 的严格正、满支撑。Sparsemax、entmax 把一部分键精确打到 0；softpick 一类算子进一步取消「必须是分布」。后课转向 KV 跨层共享，默认你已知道「归一化是可选模块」，不再把 softmax 当成注意力定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Softmax 输出 \\(p_i\\gt 0\\) 且 \\(\\sum p_i=1\\)。长序列上绝大多数键应真正不贡献，尾部的正质量却仍在稀释、仍在占存储。Sigmoid 能全关，却失去竞争，尺度要另补。缺口是：<strong>保留 argmax 式的相对比较，同时允许精确零</strong>，或允许和不为 1。</p><p>Martins 与 Astudillo 的 sparsemax 是把向量投影到单纯形，落在面上的坐标可以为 0。Entmax 在 softmax 与 sparsemax 之间用一个 \\(\\alpha\\) 插值。近期的 softpick 把「挑出若干正贡献、其余为零、不做单纯形归一」当成核，服务的是可关断加稀疏，而不是概率。</p><p><span class="marginnote">「Attention is off by one」把分母写成 \\(1+\\sum e^{z}\\)，等价于多一个永不出现的键。它仍在指数族里，本课不把它当成另一族替代，只提醒：分母微变也会改变汇的强度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Sparsemax：\\(\\mathrm{sparsemax}(z)=\\mathrm{argmin}_{p\\in\\Delta}\\|p-z\\|^2\\)，阈值以下的坐标为 0，其余平移后和为 1。Entmax\\(_\\alpha\\) 用 Tsallis 熵， \\(\\alpha=1\\) 退回 softmax，\\(\\alpha=2\\) 即 sparsemax。二者都能接在 \\(QK^\\top/\\sqrt{d_k}\\) 之后，掩码仍是非法位置先置 \\(-\\infty\\) 或移出投影。</p><p><span class="marginnote">直觉类比：softmax 像把一勺糖溶进整桶水——每个键都分到一点甜；sparsemax 像把糖只放进最甜的几杯，其余杯子精确为零。算法本体是「把 logits 向概率单纯形做投影」：离单纯形太远的坐标被直接砍到 0，剩下的平移到恰好凑成和 1。</span></p><p>Softpick 不把输出约束在 \\(\\Delta\\) 上：先用光滑函数挑出正向贡献，再按需归一或直接乘值。实现上要自己管输出尺度，思想与 sigmoid 更近，但挑的过程仍看行内相对大小，不是完全逐点。</p><h3 id="梯度与核融合" tabindex="-1">梯度与核融合 <a class="header-anchor" href="#梯度与核融合" aria-label="Permalink to &quot;梯度与核融合&quot;">​</a></h3><p>Softmax 的 Jacobian 有闭式 $ \\mathrm{diag}(p)-pp^\\top$。Sparsemax 只在支撑集上类似仿射，支撑随输入变，核要动态掩码。这就是为何生产级解码器仍默认 softmax：不是表达力最优，而是分块核、反向、混合精度都已打磨。替代函数若不能进 Flash 一类核，长上下文先不可用。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>精确零让 KV 在数学上可以跳过——若实现真去跳。多数框架仍算满矩阵，稀疏只发生在数值里，加速不明显。表达上，稀疏竞争恢复了「少数键拿走全部质量」，比 sigmoid 更像检索；比 softmax 更不像「每个键都沾一点」。Entmax 的 \\(\\alpha\\) 是在稀释与硬选择之间滑动的旋钮，训练中可学或固定。</p><p><span class="marginnote">数字实例：16K 上下文的一行注意力有 16384 个键，softmax 给每个键都分正质量（哪怕多数是 \\(10^{-8}\\) 量级）；sparsemax 若每行只保留 64 个非零，支撑就是 1/256——理论上 KV 读取省两个数量级。差别全在「核去不去跳这些零」。</span></p><p>和不为 1 时，残差写入幅度随通过质量变，注意力汇可以消失，也回到上一课的范数问题。课序上应先问要不要单纯形，再问支不支持精确零。</p>',17)),(o(),l(r,null,{default:s(()=>[i(e,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20ZERO%5B%22sparsemax%20%E5%86%99%E5%87%BA%E7%B2%BE%E7%A1%AE%E9%9B%B6%22%5D%20--%3E%20Q1%7B%22%E6%A0%B8%E6%8C%89%E9%9B%B6%E8%B7%B3%E8%BF%87%E8%AE%A1%E7%AE%97%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%22%E5%A4%9A%E6%95%B0%E6%A1%86%E6%9E%B6%EF%BC%9A%E7%AE%97%E6%BB%A1%E7%9F%A9%E9%98%B5%22%7C%20SAME%5B%22%E9%80%9F%E5%BA%A6%E4%B8%8D%E5%8F%98%EF%BC%8C%E5%8F%AA%E6%9C%89%E7%90%86%E8%AE%BA%20FLOPs%20%E5%8F%98%E5%B0%91%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%AE%9E%E7%8E%B0%E5%8A%A8%E6%80%81%E6%94%AF%E6%92%91%E9%9B%86%22%7C%20SKIP%5B%22%E6%94%AF%E6%92%91%E5%A4%96%E7%9A%84%E9%94%AE%E4%B8%8D%E8%AF%BB%22%5D%0A%20%20SKIP%20--%3E%20Q2%7B%22%E6%94%AF%E6%92%91%E9%9B%86%E5%BD%A2%E7%8A%B6%E8%A7%84%E6%95%B4%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%22%E9%9A%8F%E8%BE%93%E5%85%A5%E5%8F%98%E3%80%81%E7%A2%8E%E7%89%87%E5%8C%96%22%7C%20COST%5B%22%E5%8A%A8%E6%80%81%E6%8E%A9%E7%A0%81%E5%BC%80%E9%94%80%E5%90%83%E6%8E%89%E6%94%B6%E7%9B%8A%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%87%91%E6%88%90%E8%A7%84%E6%95%B4%E5%9D%97%22%7C%20WIN%5B%22%E5%B8%A6%E5%AE%BD%E4%B8%8E%E5%BB%B6%E8%BF%9F%E6%89%8D%E7%9C%9F%E7%9C%81%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[t("span",{class:"marginnote"},"常见误区：「输出里有零，所以更快」。零只是数字，不省任何算力——矩阵还是那个形状，注意力核还是把全部 KV 读一遍。只有当实现按支撑集动态跳过计算，稀疏才兑现成带宽和延迟；论文里的加速通常属于后一种工程。")],-1)),a[4]||(a[4]=t("p",null,[t("span",{class:"marginnote"},"头与头可以不同核，但几乎没人这么做：检查点、核、超参都会裂成按头的配置。替代发生在整层，而不是按头点菜。")],-1)),a[5]||(a[5]=t("h2",{id:"边界",tabindex:"-1"},[E("边界 "),t("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[6]||(a[6]=t("p",null,"不要在已经收敛的 softmax 模型上只换激活来「升级」。单纯形上的尖峰是训出来的，换投影会把已有头的功能打乱。评测若只看困惑度，softmax 通常仍赢；看长上下文噪声、sink、可关断，替代才有理由。下一课开始省 KV，默认层内仍是 softmax，除非显式声明。",-1)),(o(),l(r,null,{default:s(()=>[i(e,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%20logits%22%5D%20--%3E%20SM%5B%22Softmax%20%E6%BB%A1%E6%94%AF%E6%92%91%22%5D%0A%20%20Z%20--%3E%20SP%5B%22Sparsemax%20%E7%B2%BE%E7%A1%AE%E9%9B%B6%22%5D%0A%20%20Z%20--%3E%20SG%5B%22Sigmoid%20%E6%97%A0%E7%AB%9E%E4%BA%89%22%5D%0A%20%20Z%20--%3E%20PK%5B%22Softpick%20%E5%8F%AF%E5%85%B3%E6%96%AD%22%5D%0A%20%20SM%20--%3E%20V%5B%22%E4%B9%98%E5%80%BC%22%5D%0A%20%20SP%20--%3E%20V%0A%20%20SG%20--%3E%20V%0A%20%20PK%20--%3E%20V%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t("h2",{id:"小结",tabindex:"-1"},[E("小结 "),t("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[8]||(a[8]=t("ul",null,[t("li",null,"替代 softmax 的动机是稀疏、可关断或放弃概率解释，不是重推 SDPA。"),t("li",null,"Sparsemax / entmax 保留单纯形竞争并允许精确零；sigmoid / softpick 离开分布。"),t("li",null,"生产默认仍是 softmax，因为核与稳定性；数值稀疏不等于核稀疏。"),t("li",null,"换核不能当已有检查点的热修补。"),t("li",null,"出处：Martins & Astudillo, ICML 2016；sigmoid 见上一课。")],-1))])}const D=m(B,[["render",f]]);export{c as __pageData,D as default};
